package com.mohymods.kingdomsmp.gametest;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.*;
import java.util.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.storage.LevelResource;
/** Real registered Create recipes/native ingredients/physical delivery; private inputs/tier supplied, no quest proof injection. */
final class CreateCraftRuntime {
 static Item item(String id){return BuiltInRegistries.ITEM.get(ResourceLocation.parse(id));}
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();h.assertTrue(CreateCraftQuests.supported(),"Unmodified exact Create6.0.10/embedded native dependencies/registered items loaded");var id=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().equals(BlueprintRegistry.HUT)).findFirst().orElseThrow().owner();var p=server.getPlayerList().getPlayer(id);if(p==null)p=ClaimRuntimeTests.vanillaPlayer(level,id,"HallOwner");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var before=store.professions(id).track(Profession.ENGINEER);h.assertTrue(store.professions(id).isActive(Profession.ENGINEER),"Use actual saved paid Engineer enrollment, not a synthetic roster");
  var project=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.ENGINEER.buildingId())).findFirst().orElseThrow();
  if(before.completedQuestIds().containsAll(Set.of(CreateCraftQuests.ALLOY,CreateCraftQuests.COMPONENTS))){h.assertTrue(CraftQuestEvidence.count(p,Profession.ENGINEER,ProfessionRank.APPRENTICE,"create:andesite_alloy")==32&&CraftQuestEvidence.count(p,Profession.ENGINEER,ProfessionRank.APPRENTICE,"create:shaft")==56&&CraftQuestEvidence.count(p,Profession.ENGINEER,ProfessionRank.APPRENTICE,"create:cogwheel")==16&&CraftQuestEvidence.count(p,Profession.ENGINEER,ProfessionRank.APPRENTICE,"create:large_cogwheel")==8,"Second JVM retains exact actual primary recipe counts, excluding old low-tier/decompressed stock");h.assertTrue(before.xp()==300&&before.completedQuestIds().size()==3&&ConstructionService.structureIntact(level,project),"Original daily proof plus2real deliveries/300XP/Engineer premise-Ivo restore, incomplete band remains Apprentice");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("CREATE_CRAFT_RESTART_PASSED: same genuine32alloy/56shafts/16cogs/8large-cog native counters,3earned300XP/paid Workshop-Ivo/enrollment/native inventory receipt restore without repeated delivery");return;}
  h.assertTrue(before.xp()==100&&before.completedQuestIds().size()==1,"Starts from actual original native daily service100XP only");DimensionTravelRuntimeTests.seed(server,3);craft(h,p,"create:andesite_alloy",1,"minecraft:iron_nugget","minecraft:andesite","minecraft:andesite","minecraft:iron_nugget");h.assertTrue(CraftQuestEvidence.count(p,Profession.ENGINEER,ProfessionRank.APPRENTICE,"create:andesite_alloy")==0,"Tier3native crafting still works but grants no Tier4quest provenance");DimensionTravelRuntimeTests.seed(server,4);
  craft(h,p,"create:andesite_alloy",9,"create:andesite_alloy_block");h.assertTrue(CraftQuestEvidence.count(p,Profession.ENGINEER,ProfessionRank.APPRENTICE,"create:andesite_alloy")==0,"Native nine-alloy decompression cannot fabricate refined production proof");counter(p,project);boolean refused=false;try{ProfessionService.review(p,"materials:"+CreateCraftQuests.ALLOY);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Untracked real old/decompressed alloy stock cannot substitute for personal primary production");
  for(int n=0;n<32;n++)craft(h,p,"create:andesite_alloy",1,"minecraft:iron_nugget","minecraft:andesite","minecraft:andesite","minecraft:iron_nugget");h.assertTrue(CraftQuestEvidence.count(p,Profession.ENGINEER,ProfessionRank.APPRENTICE,"create:andesite_alloy")==32,"Actual32native primary recipes consumed64andesite/64iron nuggets");deliver(h,p,project,CreateCraftQuests.ALLOY);
  for(int n=0;n<7;n++)craft(h,p,"create:shaft",8,"create:andesite_alloy",null,"create:andesite_alloy");
  for(int n=0;n<16;n++)craft(h,p,"create:cogwheel",1,"create:shaft","minecraft:oak_planks");
  for(int n=0;n<8;n++)craft(h,p,"create:large_cogwheel",1,"create:shaft","minecraft:oak_planks","minecraft:oak_planks");
  h.assertTrue(p.getInventory().countItem(item("create:shaft"))==32,"Exactly32earned shaft units remain after24actual native gear recipe inputs");
  counter(p,project);var quote=ProfessionService.review(p,"materials:"+CreateCraftQuests.COMPONENTS);var saved=p.getInventory().getItem(0).copy();p.getInventory().setItem(0,new ItemStack(Items.DIRT));refused=false;try{ProfessionService.confirm(p,quote.nonce());}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Changed native inventory refuses component consumption/XP");p.getInventory().setItem(0,saved);deliver(h,p,project,CreateCraftQuests.COMPONENTS);
  var track=store.professions(id).track(Profession.ENGINEER);h.assertTrue(track.xp()==300&&track.completedQuestIds().size()==3&&p.getInventory().countItem(item("create:shaft"))==0&&p.getInventory().countItem(item("create:cogwheel"))==0&&p.getInventory().countItem(item("create:large_cogwheel"))==0,"Actual32shafts16small8large plain outputs permanently consumed/200newXPonce, no missing-band rank");h.assertTrue(EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data")).professions(id).equals(store.professions(id)),"Canonical native inventory receipts/earned roster reopen");com.mojang.logging.LogUtils.getLogger().info("CREATE_CRAFT_NATIVE_PASSED: exact Create6.0.10native primary alloy/shaft/small-large cog recipes and actual ingredient debit, Tier3noquest/old-decompression denial,32alloyDEL and32shaft16cog8largeDEL/current inventory refusal/3earned300XP/original Workshop-Ivo; explicit private input-tier supplies only");
 }
 static void craft(GameTestHelper h,ServerPlayer p,String expected,int amount,String...inputs){p.closeContainer();p.containerMenu=p.inventoryMenu;for(int slot=1;slot<=4;slot++)p.inventoryMenu.getSlot(slot).set(ItemStack.EMPTY);for(int n=0;n<inputs.length;n++)if(inputs[n]!=null)p.inventoryMenu.getSlot(n+1).set(inputs[n].equals("create:shaft")?take(p,item(inputs[n])):new ItemStack(item(inputs[n])));h.assertTrue(p.inventoryMenu.getSlot(0).getItem().is(item(expected))&&p.inventoryMenu.getSlot(0).getItem().getCount()==amount,"Exact actual native personal2x2Create recipe output "+expected);var output=p.inventoryMenu.quickMoveStack(p,0);h.assertTrue(!output.isEmpty(),"Native result extraction succeeds");for(int slot=1;slot<=4;slot++)h.assertTrue(p.inventoryMenu.getSlot(slot).getItem().isEmpty(),"Actual native crafting debits all recipe inputs");p.closeContainer();}
 static ItemStack take(ServerPlayer p,Item item){for(int i=0;i<36;i++)if(p.getInventory().getItem(i).is(item))return p.getInventory().removeItem(i,1);throw new IllegalStateException("Use actual previously crafted shaft inventory, no copied input");}
 static void counter(ServerPlayer p,ConstructionStore.Project project){var b=BlueprintRegistry.get(project.blueprint(),1);BlacksmithRepairRuntime.near(p,project.origin().offset(b.rotate(b.home(),project.rotation())));CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)p.serverLevel().getEntity(project.npc()));}
 static void deliver(GameTestHelper h,ServerPlayer p,ConstructionStore.Project project,String quest)throws Exception{counter(p,project);var q=ProfessionService.review(p,"materials:"+quest);ProfessionService.confirm(p,q.nonce());boolean refused=false;try{ProfessionService.confirm(p,q.nonce());}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Same reviewed native delivery cannot duplicate XP or consume again");CommerceService.verifyReceipt(p);}
}
